var m = RulesEngine.ork11e_ab_mods(GameState.get_unit("U_ERADICATOR_SQUAD_WITH_MELTA_RIFLES_A"), GameState.get_unit("U_DEFF_DREAD_A"), {"name": "Melta Rifle", "type": "Ranged", "keywords": ["MELTA 2"]}, false, GameState.state)
var b = RulesEngine.ork11e_ab_mods(GameState.get_unit("U_ERADICATOR_SQUAD_WITH_MELTA_RIFLES_A"), GameState.get_unit("U_DEFF_DREAD_A"), {"name": "Bolt Pistol", "type": "Ranged", "keywords": ["PISTOL"]}, false, GameState.state)
return "%d,%d" % [int(m.get("strength", 0)), int(b.get("strength", 0))]

var aid := "U_ERADICATOR_SQUAD_WITH_HEAVY_BOLTERS_A"
var wid := ""
var w = RulesEngine.get_unit_weapons(aid, GameState.state)
var mids: Array = []
for mid in w:
	for x in w[mid]:
		if str(x).begins_with("heavy_bolter"):
			wid = str(x)
			mids.append(str(mid))
var asg = {"weapon_id": wid, "target_unit_id": "U_BOYZ_B", "model_ids": mids}
var on_b: Dictionary = GameState.state.duplicate(true)
var off_b: Dictionary = GameState.state.duplicate(true)
off_b.units[aid].flags.erase("sm11e_abc_overlap")
var on = RulesEngine.resolve_shoot({"type": "SHOOT", "actor_unit_id": aid, "payload": {"assignments": [asg]}}, on_b, RulesEngine.RNGService.new(11))
var off = RulesEngine.resolve_shoot({"type": "SHOOT", "actor_unit_id": aid, "payload": {"assignments": [asg]}}, off_b, RulesEngine.RNGService.new(11))
var a_on := 0
var a_off := 0
for d in on.get("dice", []):
	if str(d.get("context", "")) == "to_hit":
		a_on += d.get("rolls_raw", []).size()
for d in off.get("dice", []):
	if str(d.get("context", "")) == "to_hit":
		a_off += d.get("rolls_raw", []).size()
print("[sm11e-m4c] overlapping destruction: heavy bolter attacks %d with vs %d without" % [a_on, a_off])
return a_on - a_off

DebugLogger._flush_buffer()
var f = FileAccess.open(DebugLogger.get_real_log_file_path(), FileAccess.READ)
var n := 0
while f != null and not f.eof_reached():
	var l := f.get_line()
	if l.contains("[ERROR"):
		n += 1
		print("[sm11e-m4c] debug-log ERROR: ", l)
return n
